import React, { useState, useEffect, useContext } from 'react';
import { Alert } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { loginUserValidate } from './operation';
import { FaEye, FaEyeSlash, FaLock, FaUserAlt, FaGraduationCap, FaUniversity } from 'react-icons/fa';
import { emailValidation } from '../../services/commonUtills/FormValidations';
import { AuthContext } from '../../App';

const initialState = {
  emlid: '',
  pswrd: '',
};

function Login() {
  const { dispatchAuth } = useContext(AuthContext);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [alertShow, setAlertShow] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertVarient, setAlertVarient] = useState('');
  const [showPassword, setShowPassword] = useState(true);
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    dispatchAuth({ type: 'LOGOUT' });
  }, [dispatchAuth]);

  const handleChange = (e) => {
    const { id, value } = e.target;
    if (id === 'email') {
      const normalizedEmail = value.toLowerCase();
      setEmail(normalizedEmail);
      setEmailError('');
    } else if (id === 'pswrd') {
      setPassword(value);
      setPasswordError('');
    }
  };

  const validateData = () => {
    let is_valid = true;
    if (!email) {
      setEmailError('Please Enter Email or Mobile');
      is_valid = false;
    } else if (!emailValidation(email) && !/^[0-9]{10}$/.test(email)) {
      setEmailError('Please Enter Valid Email or 10-digit Mobile');
      is_valid = false;
    }
    if (!password) {
      setPasswordError('Please Enter Password');
      is_valid = false;
    }
    return is_valid;
  };

  const handleSubmit = () => {
    if (validateData()) {
      setIsLoading(true);
      loginAuthentication();
    }
  };

  const loginAuthentication = async () => {
    const obj = { ...initialState, emlid: email, pswrd: password };
    const res = await loginUserValidate(obj);

    if (res && res.status === 'success') {
      setAlertShow(true);
      setAlertMessage('Logged In Successfully');
      setAlertVarient('success');
      hideMessage();
      dispatchAuth({ type: 'LOGIN', payload: { user: res.payload } });
      navigate('/dashboard');
    } else {
      setAlertShow(true);
      setAlertMessage(
        res?.error?.message || 'Please Enter Valid Details'
      );
      setAlertVarient('danger');
      hideMessage();
      setIsLoading(false);
    }
  };

  const hideMessage = () => {
    setTimeout(() => {
      setAlertShow(false);
      setAlertMessage('');
      setAlertVarient('');
    }, 5000);
  };

  const showHidePassword = () => setShowPassword(!showPassword);

  const loginEnter = (e) => {
    if (e.key === 'Enter') {
      handleSubmit();
    }
  };

  return (
    <>
      <Alert
        className="notification"
        variant={alertVarient}
        show={alertShow}
        onClose={() => setAlertShow(false)}
        dismissible
        style={{
          position: 'fixed',
          top: '20px',
          right: '20px',
          zIndex: 9999,
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
        }}
      >
        {alertMessage}
      </Alert>

      <div className="login-container-new">
        <style>{`
          .login-container-new {
            display: flex;
            min-height: 100vh;
            width: 100%;
            background-color: #f3f4f6;
            font-family: 'Inter', sans-serif;
          }
          .login-left-panel-new {
            flex: 0 0 50%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: space-between;
            padding: 4rem 3rem;
            position: relative;
            overflow: hidden;
            background: linear-gradient(135deg, #06154b 0%, #0a1b5c 40%, #0d2383 75%, #1e3a8a 100%);
          }
          .login-right-panel-new {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 2rem;
            background-color: #f8fafc;
          }
          .login-input-group {
            display: flex;
            align-items: stretch;
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            overflow: hidden;
            background-color: #fff;
            transition: all 0.2s ease-in-out;
            box-shadow: 0 1px 2px rgba(0,0,0,0.05);
          }
          .login-input-group:focus-within {
            border-color: #3b82f6 !important;
            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15) !important;
          }
          .login-btn-primary {
            background-color: #2f54eb;
            color: #fff;
            border: none;
            border-radius: 8px;
            font-weight: 600;
            padding: 0.75rem 1.5rem;
            width: 100%;
            transition: all 0.2s ease-in-out;
            cursor: pointer;
            box-shadow: 0 2px 4px rgba(47, 84, 235, 0.15);
          }
          .login-btn-primary:hover {
            background-color: #1d39c4;
          }
          .login-btn-primary:disabled {
            background-color: #adc6ff;
            cursor: not-allowed;
          }
          @media (max-width: 768px) {
            .login-left-panel-new {
              display: none !important;
            }
            .login-right-panel-new {
              flex: 1;
              padding: 1.5rem;
            }
          }
        `}</style>

        {/* Left Panel */}
        <div className="login-left-panel-new">
          <div style={{
            position: 'absolute',
            top: '-10%',
            left: '-10%',
            width: '60%',
            height: '60%',
            borderRadius: '50%',
            background: 'radial-gradient(circle, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0) 70%)',
            zIndex: 1
          }} />
          <div style={{
            position: 'absolute',
            bottom: '-10%',
            right: '-10%',
            width: '70%',
            height: '70%',
            borderRadius: '50%',
            background: 'radial-gradient(circle, rgba(255,255,255,0.04) 0%, rgba(255,255,255,0) 70%)',
            zIndex: 1
          }} />
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', flex: 1, zIndex: 2, width: '100%' }}>
            <div style={{ marginBottom: '1.5rem', color: '#fff' }}>
              <FaGraduationCap size={90} />
            </div>
            <h1 style={{ color: '#fff', fontSize: '2.25rem', fontWeight: 700, marginBottom: '0.75rem', textAlign: 'center' }}>
              Welcome <span style={{ color: '#90caf9' }}>Back!</span>
            </h1>
            <p style={{ color: 'rgba(255, 255, 255, 0.75)', fontSize: '0.95rem', textAlign: 'center', maxWidth: '320px', lineHeight: 1.5, margin: 0 }}>
              Sign in to access your student, staff, or transport dashboard.
            </p>
          </div>
        </div>

        {/* Right Panel */}
        <div className="login-right-panel-new">
          <div style={{
            background: '#fff',
            borderRadius: '16px',
            boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.05)',
            border: '1px solid rgba(241, 245, 249, 0.8)',
            padding: '2.75rem 2.5rem 2.25rem',
            width: '100%',
            maxWidth: '430px',
          }}>
            <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
              <div style={{
                width: '64px',
                height: '64px',
                borderRadius: '16px',
                backgroundColor: '#eff6ff',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#2f54eb',
              }}>
                <FaUniversity size={28} />
              </div>
              <h2 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b', margin: '1rem 0 0.25rem' }}>
                Institute User Portal
              </h2>
              <p style={{ color: '#64748b', fontSize: '0.875rem', margin: 0 }}>
                Sign in with email or mobile number
              </p>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              {/* Email / Mobile */}
              <div>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, color: '#475569', marginBottom: '0.5rem', textAlign: 'left' }}>
                  Email or Mobile
                </label>
                <div className={`login-input-group ${emailError ? 'error' : ''}`} style={emailError ? { borderColor: '#ef4444' } : {}}>
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '46px',
                    backgroundColor: '#eff6ff',
                    color: '#2f54eb',
                    borderRight: '1px solid #e2e8f0',
                  }}>
                    <FaUserAlt size={14} />
                  </div>
                  <input
                    id="email"
                    type="text"
                    placeholder="you@example.com or 9xxxxxxxxx"
                    value={email}
                    onChange={handleChange}
                    onKeyDown={loginEnter}
                    style={{
                      flex: 1,
                      border: 'none',
                      outline: 'none',
                      padding: '0.75rem 1rem',
                      fontSize: '0.925rem',
                      color: '#0f172a',
                      backgroundColor: 'transparent',
                    }}
                  />
                </div>
                {emailError && (
                  <div style={{ color: '#ef4444', fontSize: '0.78rem', marginTop: '0.35rem', textAlign: 'left', fontWeight: 500 }}>
                    {emailError}
                  </div>
                )}
              </div>

              {/* Password */}
              <div>
                <label style={{ display: 'block', fontSize: '0.85rem', fontWeight: 600, color: '#475569', marginBottom: '0.5rem', textAlign: 'left' }}>
                  Password
                </label>
                <div className={`login-input-group ${passwordError ? 'error' : ''}`} style={passwordError ? { borderColor: '#ef4444' } : {}}>
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '46px',
                    backgroundColor: '#eff6ff',
                    color: '#2f54eb',
                    borderRight: '1px solid #e2e8f0',
                  }}>
                    <FaLock size={14} />
                  </div>
                  <input
                    id="pswrd"
                    type={showPassword ? 'password' : 'text'}
                    placeholder="••••••••"
                    value={password}
                    onChange={handleChange}
                    onKeyDown={loginEnter}
                    style={{
                      flex: 1,
                      border: 'none',
                      outline: 'none',
                      padding: '0.75rem 1rem',
                      fontSize: '0.925rem',
                      color: '#0f172a',
                      backgroundColor: 'transparent',
                    }}
                  />
                  <div
                    onClick={showHidePassword}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      padding: '0 1rem',
                      cursor: 'pointer',
                      color: '#94a3b8',
                    }}
                  >
                    {showPassword ? <FaEyeSlash size={16} /> : <FaEye size={16} />}
                  </div>
                </div>
                {passwordError && (
                  <div style={{ color: '#ef4444', fontSize: '0.78rem', marginTop: '0.35rem', textAlign: 'left', fontWeight: 500 }}>
                    {passwordError}
                  </div>
                )}
              </div>
            </div>

            <div style={{ marginTop: '1.75rem' }}>
              <button className="login-btn-primary" onClick={handleSubmit} disabled={isLoading}>
                {isLoading ? 'Logging In...' : 'Login'}
              </button>
            </div>
          </div>

          <p style={{ color: '#94a3b8', fontSize: '0.75rem', marginTop: '2rem', textAlign: 'center' }}>
            © 2026 Institute Management System - User Portal. All rights reserved.
          </p>
        </div>
      </div>
    </>
  );
}

export default Login;
